<?php
namespace Azula\SmsStudio;
final class M8AnalyticsCsv
{
    private static function money($minor):string{return $minor===null?'Unavailable':intdiv((int)$minor,100).'.'.str_pad((string)((int)$minor%100),2,'0',STR_PAD_LEFT);}
    public static function chunks(array $report):\Generator
    {
        $header=['Campaign','Segment','Campaigns sent in period','Raw link requests','Unique observed browsers','Unique recipient links accessed','Observed page events','Product view events','Product unique tracked recipients','Add-to-cart events','Cart unique tracked recipients','Cart event value EGP (not sales)','Cart missing/foreign values','Checkout events','Checkout unique tracked recipients','Checkout event value EGP (not sales)','Checkout missing/foreign values','Latest checkout values EGP (not sales)','Attributed purchases','Unique tracked purchasing recipients','Attributed revenue EGP after refunds','Potential unfinished checkout value EGP (not sales)','Potential unfinished recipient records','Still observing records','Uncertain checkout records','Verified provider cost units (not EGP)','Missing provider costs'];
        if(RC1Status::modern())$header=str_replace(['Cart event value EGP (not sales)','Checkout event value EGP (not sales)'],['Latest known added-item values per campaign-recipient EGP (not sales)','Latest known checkout values per campaign-recipient EGP (not sales)'],$header);if(M9Schema::modern())$header[]='Unique clicked campaign-recipient records';
        yield "\xEF\xBB\xBF".AudienceCsv::line($header);$finance=$report['coverage']['attribution_contract']&&$report['coverage']['finance_contract']&&(int)$report['coverage']['finance_pending']===0;
        foreach($report['rows'] as $row){$v=$row['m8'];$cart=$v['add_to_cart'];$check=$v['checkout_start'];$ab=$v['abandonment'];$cells=[$row['name'],$row['segment'],$v['campaigns_sent'],$row['link_requests'],$row['unique_clicks'],$row['recipient_links_accessed'],$v['visit']['events'],$v['product_view']['events'],$v['product_view']['unique_recipients']??'Unavailable',$cart['events'],$cart['unique_recipients']??'Unavailable',self::money($cart['value_minor']),$cart['missing_values'],$check['events'],$check['unique_recipients']??'Unavailable',self::money($check['value_minor']),$check['missing_values'],self::money($ab['latest_checkout_minor']??null),$finance?$row['purchases']:'Unavailable',$finance?($v['purchase']['unique_recipients']??'Unavailable'):'Unavailable',$finance?self::money($row['revenue_minor']):'Unavailable',self::money($ab['potential_minor']),$ab['potential_recipients'],$ab['observing'],$ab['uncertain'],$row['provider_cost']['reported']??'Not reported by provider',$row['provider_cost']['missing']??'Unavailable'];if(M9Schema::modern())$cells[]=$row['m9']['unique_clicked_recipients']??'Unavailable';yield AudienceCsv::line(array_map(fn($v)=>AudienceCsv::cell((string)$v),$cells));}
    }
}
